window.docContents[106].resolve({"/Taking-Terms-Apart/#views":{"contents":"Building terms is half of the story: a solver hands terms back — models, unsat cores, proofs, synthesized functions — and a rewrite has to look inside a term before it replaces it. cvc.lean takes a term apart through a view: the term one level down, its operator as a constructor and its kids, indices and names as fields.\n\nimport Cvc.Typed.View (or Cvc.Untyped.View) brings in everything this chapter uses; import Cvc includes it.\n\n\n\n\n\n","context":"Cvc.lean -- High-Level API for CVC5","header":"5. Taking Terms Apart","id":"/Taking-Terms-Apart/#views"}});